// Chunks: create_chunk + grow_chunk (one tx, stage 1; grow is permissionless),
// populate_chunk (stage 2, permissionless), set_spawn, close_chunk (refund). Generated bytes are compared with
// magicraft-core's reference output (crates/core/examples/gen.rs).
import { expect } from "chai";
import { web3 } from "@anchor-lang/core";
import { erConn, erProgram, sendEr } from "./helpers/env";
import { setupPlayer, TestPlayer } from "./helpers/player";
import {
  chunkData,
  chunkHeader,
  chunkPda,
  CHUNK_BLOCKS_OFFSET,
  CHUNK_FULL_LEN,
  CHUNK_INITIAL_LEN,
  CHUNK_TOTAL_RENT,
  closeChunkIx,
  computeBudgetIx,
  createAndGrow,
  createChunkIx,
  GEN_CREATED,
  GEN_DONE,
  GEN_STAGE1,
  growChunkIx,
  ixCus,
  populate,
  presencePda,
  PRESENCE_EMPTY_LEN,
  RefChunk,
  referenceChunk,
  setSpawnIx,
} from "./helpers/chunk";
import {
  createWorldIx,
  fails,
  fetchWorld,
  freshNonce,
  setupWorld,
  TestWorld,
  worldPda,
} from "./helpers/world";

const FP = 256;

async function erLamports(pk: web3.PublicKey): Promise<number> {
  return (await erConn.getAccountInfo(pk, "confirmed"))?.lamports ?? 0;
}

async function openChunks(p: TestPlayer): Promise<number> {
  return (await p.er.account.player.fetch(p.player)).openChunks;
}

async function chunkCount(world: web3.PublicKey): Promise<number> {
  return (await fetchWorld(world))!.acc.chunkCount;
}

const blocksOf = (d: Buffer) =>
  d.subarray(CHUNK_BLOCKS_OFFSET, CHUNK_BLOCKS_OFFSET + 16_384);

/** First differing index of two buffers (-1 if equal), for readable failures. */
function firstDiff(a: Buffer, b: Buffer): number {
  if (a.length !== b.length) return Math.min(a.length, b.length);
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return i;
  return -1;
}

function expectMobs(d: Buffer, ref: RefChunk, cx: number, cz: number) {
  const mobs = chunkHeader(d).mobs;
  for (let i = 0; i < 8; i++) {
    const m = mobs.subarray(i * 32, i * 32 + 32);
    const s = ref.spawns[i];
    if (!s) {
      expect(
        m.every((b) => b === 0),
        `mob slot ${i} empty`
      ).to.equal(true);
      continue;
    }
    expect(m[0], `mob ${i} kind`).to.equal(s.kind);
    expect(m[1], `mob ${i} hp`).to.be.greaterThan(0);
    expect(m.readInt32LE(4)).to.equal((cx * 16 + s.x) * FP + FP / 2);
    expect(m.readInt32LE(8)).to.equal(s.y * FP);
    expect(m.readInt32LE(12)).to.equal((cz * 16 + s.z) * FP + FP / 2);
  }
}

describe("chunks", () => {
  let tw: TestWorld;
  let p: TestPlayer;
  let world: web3.PublicKey;
  const refs = new Map<string, RefChunk>();
  const ref = (cx: number, cz: number) => {
    const k = `${cx},${cz}`;
    if (!refs.has(k)) refs.set(k, referenceChunk(tw.seed, cx, cz));
    return refs.get(k)!;
  };
  const c00 = () => chunkPda(world, 0, 0);
  const c10 = () => chunkPda(world, 1, 0);
  /** A fresh 0-lamport fee payer (permissionless ixs). */
  const stranger = () => web3.Keypair.generate();

  before(async () => {
    tw = await setupWorld({ depositSol: 0.05 });
    ({ p, world } = tw);
    ref(0, 0); // builds the gen example once (cargo) before the timed tests
  });

  it("create_chunk on an unseeded world → SeedPending", async () => {
    const nonce = freshNonce();
    await sendEr([await createWorldIx(p, { nonce })], [p.authority]);
    const w = worldPda(p.authority.publicKey, nonce);
    const err = await fails(
      sendEr([await createChunkIx(p, w, 0, 0)], [p.authority])
    );
    expect(err?.code, String(err)).to.equal("SeedPending");
  });

  it("the first chunk must be (0,0): (2,0) without a neighbor → NotAdjacent", async () => {
    const err = await fails(
      sendEr([await createChunkIx(p, world, 2, 0)], [p.authority])
    );
    expect(err?.code, String(err)).to.equal("NotAdjacent");
  });

  it("create + grow (0,0) in one tx: stage-1 bytes equal magicraft-core, exact rent", async () => {
    const before = await erLamports(p.player);
    const sig = await createAndGrow(p, world, 0, 0);
    const { ixs, total } = await ixCus(sig);
    console.log(
      `    CU create_chunk ${ixs[0]}, grow_chunk ${ixs[1]}; tx total ${total}`
    );
    expect(total).to.be.lessThan(1_200_000);

    const after = await erLamports(p.player);
    expect(before - after).to.equal(CHUNK_TOTAL_RENT);
    expect(CHUNK_TOTAL_RENT).to.equal(
      (CHUNK_FULL_LEN + 60) * 32 + (PRESENCE_EMPTY_LEN + 60) * 32
    );

    const d = (await chunkData(c00()))!;
    expect(d.length).to.equal(CHUNK_FULL_LEN);
    const h = chunkHeader(d);
    expect(h.payer.toBase58()).to.equal(p.player.toBase58());
    expect(h.world.toBase58()).to.equal(world.toBase58());
    expect([h.cx, h.cz, h.genStage, h.edited]).to.deep.equal([
      0,
      0,
      GEN_STAGE1,
      0,
    ]);
    expect(h.taskId).to.equal(0n);
    const r = ref(0, 0);
    expect(firstDiff(blocksOf(d), r.stage1), "stage-1 blocks").to.equal(-1);
    expect(firstDiff(Buffer.from(h.biomes), r.biomes), "biomes").to.equal(-1);

    const pres = (await erConn.getAccountInfo(
      presencePda(c00()),
      "confirmed"
    ))!;
    expect(pres.data.length).to.equal(PRESENCE_EMPTY_LEN);
    expect(pres.owner.toBase58()).to.equal(erProgram.programId.toBase58());
    expect(new web3.PublicKey(pres.data.subarray(8, 40)).toBase58()).to.equal(
      c00().toBase58()
    );
    expect(pres.data.readUInt16LE(42)).to.equal(0);

    expect(await openChunks(p)).to.equal(1);
    expect(await chunkCount(world)).to.equal(1);
  });

  it("grow_chunk twice → WrongGenStage", async () => {
    const err = await fails(
      sendEr(
        [computeBudgetIx(), await growChunkIx(p.player, world, 0, 0)],
        [stranger()]
      )
    );
    expect(err?.code, String(err)).to.equal("WrongGenStage");
  });

  it("a neighbor that is not DONE is no foothold (ChunkNotReady); set_spawn before populate → ChunkNotReady", async () => {
    let err = await fails(
      sendEr(
        [await createChunkIx(p, world, 1, 0, { neighbor: c00() })],
        [p.authority]
      )
    );
    expect(err?.code, String(err)).to.equal("ChunkNotReady");
    err = await fails(sendEr([await setSpawnIx(world)], [stranger()]));
    expect(err?.code, String(err)).to.equal("ChunkNotReady");
  });

  it("populate (0,0) by a 0-lamport stranger, then set_spawn: bytes, animals and spawn equal magicraft-core", async () => {
    const sig = await populate(world, 0, 0);
    const { ixs, total } = await ixCus(sig);
    console.log(`    CU populate_chunk ${ixs[0]}; tx total ${total}`);
    expect(total).to.be.lessThan(1_200_000);

    const d = (await chunkData(c00()))!;
    const r = ref(0, 0);
    expect(chunkHeader(d).genStage).to.equal(GEN_DONE);
    expect(firstDiff(blocksOf(d), r.blocks), "final blocks").to.equal(-1);
    expectMobs(d, r, 0, 0);
    expect((await fetchWorld(world))!.acc.spawnSet).to.equal(false);

    const ss = await sendEr([await setSpawnIx(world)], [stranger()]);
    console.log(
      `    CU set_spawn ${(await ixCus(ss)).ixs[0]}; (0,0): ${
        r.spawns.length
      } animals; spawn ${JSON.stringify(r.spawn)}`
    );
    const w = (await fetchWorld(world))!.acc;
    expect(w.spawnSet).to.equal(true);
    expect(w.spawn).to.deep.equal(r.spawn);
  });

  it("set_spawn twice → SpawnAlreadySet; populate twice → WrongGenStage", async () => {
    let err = await fails(sendEr([await setSpawnIx(world)], [stranger()]));
    expect(err?.code, String(err)).to.equal("SpawnAlreadySet");
    err = await fails(populate(world, 0, 0));
    expect(err?.code, String(err)).to.equal("WrongGenStage");
  });

  it("(0,0) again → fails (exists); a diagonal or distant neighbor → NotAdjacent", async () => {
    expect(
      await fails(sendEr([await createChunkIx(p, world, 0, 0)], [p.authority])),
      "duplicate create"
    ).to.not.equal(null);
    for (const [cx, cz] of [
      [1, 1],
      [2, 0],
    ]) {
      const err = await fails(
        sendEr(
          [await createChunkIx(p, world, cx, cz, { neighbor: c00() })],
          [p.authority]
        )
      );
      expect(err?.code, `(${cx},${cz}) ${err}`).to.equal("NotAdjacent");
    }
  });

  it("a neighbor from another world → InvalidChunk", async () => {
    const other = await setupWorld({ player: p });
    await createAndGrow(p, other.world, 0, 0);
    const err = await fails(
      sendEr(
        [
          await createChunkIx(p, world, 1, 0, {
            neighbor: chunkPda(other.world, 0, 0),
          }),
        ],
        [p.authority]
      )
    );
    expect(err?.code, String(err)).to.equal("InvalidChunk");
    // Reclaim it so the Player's counters below stay simple.
    await sendEr([await closeChunkIx(p, other.world, 0, 0)], [p.authority]);
  });

  it("squatted (1,0): populate before grow → WrongGenStage; a stranger grows it (payer sponsors)", async () => {
    const sig = await sendEr(
      [await createChunkIx(p, world, 1, 0, { neighbor: c00() })],
      [p.authority]
    );
    console.log(`    CU create_chunk alone: ${(await ixCus(sig)).ixs[0]}`);
    const d = (await chunkData(c10()))!;
    expect(d.length).to.equal(CHUNK_INITIAL_LEN);
    expect(chunkHeader(d).genStage).to.equal(GEN_CREATED);

    let err = await fails(populate(world, 1, 0));
    expect(err?.code, String(err)).to.equal("WrongGenStage");

    // Another Player as sponsor → InvalidChunk.
    const q = await setupPlayer({ depositSol: 0.01 });
    err = await fails(
      sendEr(
        [computeBudgetIx(), await growChunkIx(q.player, world, 1, 0)],
        [stranger()]
      )
    );
    expect(err?.code, String(err)).to.equal("InvalidChunk");

    // A 0-lamport stranger grows it; the payer's Player pays the resize delta.
    const before = await erLamports(p.player);
    const g = await sendEr(
      [computeBudgetIx(), await growChunkIx(p.player, world, 1, 0)],
      [stranger()]
    );
    console.log(`    CU grow_chunk alone: ${(await ixCus(g)).ixs[0]}`);
    expect(before - (await erLamports(p.player))).to.equal(
      (CHUNK_FULL_LEN - CHUNK_INITIAL_LEN) * 32
    );
    const d2 = (await chunkData(c10()))!;
    expect(chunkHeader(d2).genStage).to.equal(GEN_STAGE1);
    expect(firstDiff(blocksOf(d2), ref(1, 0).stage1)).to.equal(-1);
    expect(await openChunks(p)).to.equal(2);
    expect(await chunkCount(world)).to.equal(2);
  });

  it("a stage-0 chunk closes with the 10 240-byte refund", async () => {
    await sendEr(
      [await createChunkIx(p, world, 0, 1, { neighbor: c00() })],
      [p.authority]
    );
    const before = await erLamports(p.player);
    await sendEr([await closeChunkIx(p, world, 0, 1)], [p.authority]);
    expect((await erLamports(p.player)) - before).to.equal(
      (CHUNK_INITIAL_LEN + 60) * 32 + (PRESENCE_EMPTY_LEN + 60) * 32
    );
    expect(await openChunks(p)).to.equal(2);
  });

  it("populate (1,0): matches magicraft-core; spawn unchanged", async () => {
    const spawn = (await fetchWorld(world))!.acc.spawn;
    const sig = await populate(world, 1, 0);
    console.log(`    CU populate_chunk (1,0) ${(await ixCus(sig)).ixs[0]}`);
    const d = (await chunkData(c10()))!;
    expect(firstDiff(blocksOf(d), ref(1, 0).blocks)).to.equal(-1);
    expectMobs(d, ref(1, 0), 1, 0);
    expect((await fetchWorld(world))!.acc.spawn).to.deep.equal(spawn);
  });

  it("close_chunk by another Player → Unauthorized", async () => {
    const q = await setupPlayer({ depositSol: 0.01 });
    const err = await fails(
      sendEr([await closeChunkIx(q, world, 1, 0)], [q.authority])
    );
    expect(err?.code, String(err)).to.equal("Unauthorized");
  });

  it("a chunk with passive animals closes (exact refund); regenerating brings them back", async () => {
    // First chunk along +x (from (1,0)) whose populate spawns animals.
    let k = 1;
    while (ref(k, 0).spawns.length === 0) {
      k++;
      if (k > 30) throw new Error("no chunk with animals in (1..30, 0)");
    }
    for (let i = 2; i <= k; i++) {
      await createAndGrow(p, world, i, 0, chunkPda(world, i - 1, 0));
      await populate(world, i, 0);
    }
    const ck = chunkPda(world, k, 0);
    expectMobs((await chunkData(ck))!, ref(k, 0), k, 0);
    const opened = await openChunks(p);
    const count = await chunkCount(world);
    const before = await erLamports(p.player);
    const sig = await sendEr(
      [await closeChunkIx(p, world, k, 0)],
      [p.authority]
    );
    console.log(
      `    (${k},0) with ${
        ref(k, 0).spawns.length
      } animals closed; CU close_chunk ${(await ixCus(sig)).ixs[0]}`
    );
    expect((await erLamports(p.player)) - before).to.equal(CHUNK_TOTAL_RENT);
    expect(await chunkData(ck)).to.equal(null);
    expect(await erConn.getAccountInfo(presencePda(ck), "confirmed")).to.equal(
      null
    );
    expect(await openChunks(p)).to.equal(opened - 1);
    expect(await chunkCount(world)).to.equal(count - 1);

    await createAndGrow(p, world, k, 0, chunkPda(world, k - 1, 0));
    await populate(world, k, 0);
    const d = (await chunkData(ck))!;
    expect(firstDiff(blocksOf(d), ref(k, 0).blocks)).to.equal(-1);
    expectMobs(d, ref(k, 0), k, 0);
  });

  it("a stage-1 chunk closes with an exact refund; regenerating it is byte-identical", async () => {
    const before = await erLamports(p.player);
    await createAndGrow(p, world, -1, 0, c00());
    const opened = await openChunks(p);
    const count = await chunkCount(world);
    await sendEr([await closeChunkIx(p, world, -1, 0)], [p.authority]);
    expect(await erLamports(p.player)).to.equal(before);
    expect(await chunkData(chunkPda(world, -1, 0))).to.equal(null);
    expect(await openChunks(p)).to.equal(opened - 1);
    expect(await chunkCount(world)).to.equal(count - 1);

    // A different CU limit keeps this tx distinct from the first create + grow, which may
    // still be within the same blockhash ("already processed" otherwise).
    await createAndGrow(p, world, -1, 0, c00(), 1_399_999);
    await populate(world, -1, 0);
    const d = (await chunkData(chunkPda(world, -1, 0)))!;
    expect(firstDiff(blocksOf(d), ref(-1, 0).blocks)).to.equal(-1);
    expectMobs(d, ref(-1, 0), -1, 0);
  });
});
